  const handleAutoEmail=(d)=>{ if(!d) return; const isApp=isApplicantRow(d); const subject=isApp?`Pinnacle Security Ltd - Your Application for ${getVal(d,['Position','position'])||'Security Officer'} - Received`:`Pinnacle Security Ltd - Your ${getVal(d,['Service','service'])||'Security Service'} Enquiry - Received`; const body=fillTemplate(isApp?autoSettings.applicantEmail:autoSettings.contactEmail,d); fetch(GOOGLE_SHEET_WEBHOOK,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:'autoReplyEmail',Timestamp:getVal(d,['Timestamp','timestamp']),to:getVal(d,['Email','email']),subject,body})}); const ts=getVal(d,['Timestamp','timestamp']); if(ts&&!autoReplied.includes(ts)){ const nr=[...autoReplied,ts]; setAutoReplied(nr); localStorage.setItem('psl_auto_replied',JSON.stringify(nr)); } showToast(`Auto Email sent to ${titleCase(getVal(d,['FullName','fullName']))}`); };
  const handleDelete=async(row)=>{ if(!row) return; if(!confirm(`Move ${titleCase(getVal(row,['FullName','fullName']))} to Trash?`)) return; const ts=getVal(row,['Timestamp','timestamp']); const nt=[{...row,deletedAt:new Date().toISOString()},...trash].slice(0,200); setTrash(nt); localStorage.setItem('psl_trash',JSON.stringify(nt)); setData(prev=>prev.filter(r=>r._uid!==row._uid)); setSelected(prev=>prev.filter(id=>id!==row._uid)); showToast(`${titleCase(getVal(row,['FullName','fullName']))} moved to Trash`); await fetch(GOOGLE_SHEET_WEBHOOK,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:'delete',timestamps:[ts],Timestamp:ts})}); };
