  const clearDuplicates=()=>{ const seen=new Set(); const dups=[]; const keep=[]; data.forEach(r=>{const key=getVal(r,['Phone','phone'])+"_"+getVal(r,['FullName','fullName']); if(seen.has(key)) dups.push(r); else{seen.add(key); keep.push(r);}}); if(dups.length===0){showToast('No duplicates'); return;} if(!confirm(`Found ${dups.length} duplicates?`)) return; setTrash(prev=>{const nt=[...dups,...prev].slice(0,200); localStorage.setItem('psl_trash',JSON.stringify(nt)); return nt;}); setData(keep); showToast(`${dups.length} moved`); };
  const handleEdit=(row)=>{ if(!row) return; setEditRow(row); setForm({FullName:titleCase(getVal(row,['FullName','fullName'])),Phone:getVal(row,['Phone','phone']),Email:getVal(row,['Email','email']),Service:getVal(row,['Service','service']),Message:getVal(row,['Message','Messages','message','messages']),Position:getVal(row,['Position','position']),Education:getVal(row,['Education','education']),District:getVal(row,['District','district']),Experience:getVal(row,['Experience','experience']),Interest:getVal(row,['Interest','interest']),Status:getVal(row,['Status','status'])||'New',timestamp:getVal(row,['Timestamp','timestamp']),origTimestamp:getVal(row,['Timestamp','timestamp']),_uid:row._uid,Type:isApplicantRow(row)?"applicant":"contact"}); };
  const handleSave=async()=>{ if(!editRow) return; const origTs=editRow.Timestamp||editRow.timestamp||form.origTimestamp||form.timestamp; const uid=editRow._uid||form._uid; const clean={FullName:titleCase(form.FullName||''),Phone:String(form.Phone||''),Email:String(form.Email||''),Service:titleCase(form.Service||''),Message:String(form.Message||''),Position:titleCase(form.Position||''),Education:titleCase(form.Education||''),District:titleCase(form.District||''),Experience:String(form.Experience||''),Interest:String(form.Interest||''),Status:form.Status||'New',Type:form.Type||(isApplicantRow(editRow)?"applicant":"contact")}; localStorage.setItem(`psl_${origTs}`,JSON.stringify({Status:clean.Status})); setData(prev=>prev.map(r=>r._uid===uid?{...r,...clean,Messages:clean.Message,message:clean.Message,Timestamp:origTs,timestamp:origTs,Status:clean.Status}:r)); setEditRow(null); setForm({}); showToast("Saved - Sending to Sheet..."); try{ await fetch(GOOGLE_SHEET_WEBHOOK,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:'edit',Sheet:clean.Type==='applicant'?'Applicants':'Contacts',Type:clean.Type,Timestamp:origTs,timestamp:origTs,origTimestamp:origTs,FullName:clean.FullName,Phone:clean.Phone,Email:clean.Email,Service:clean.Service,Message:clean.Message,Messages:clean.Message,Position:clean.Position,Education:clean.Education,District:clean.District,Experience:clean.Experience,Interest:clean.Interest,Status:clean.Status})}); showToast("✅ Updated in Admin & Sheet"); }catch(e){showToast("✅ Updated in Admin");} };
